// Aggregazione e strutturazione dei dati da tutte le fonti
const items = $input.all();

// Struttura per l'analisi
const aggregatedData = {
  timestamp: new Date().toISOString(),
  period: 'last_30_days',

  // Dati PrestaShop
  prestashop: {
    orders: [],
    products: [],
    summary: {
      totalOrders: 0,
      totalRevenue: 0,
      avgOrderValue: 0
    }
  },

  // Dati BigQuery
  bigquery: {
    analyticsData: [],
    productPerformance: []
  },

  // Dati Google Analytics
  googleAnalytics: {
    trafficData: [],
    summary: {
      totalUsers: 0,
      totalSessions: 0,
      totalConversions: 0,
      totalRevenue: 0
    }
  }
};

// Processa ogni item
items.forEach(item => {
  const data = item.json;

  // Identifica e categorizza i dati
  if (data.orders) {
    aggregatedData.prestashop.orders = data.orders;
    aggregatedData.prestashop.summary.totalOrders = data.orders.length;
    const revenue = data.orders.reduce((sum, o) => sum + parseFloat(o.total_paid || 0), 0);
    aggregatedData.prestashop.summary.totalRevenue = revenue;
    aggregatedData.prestashop.summary.avgOrderValue = revenue / (data.orders.length || 1);
  }

  if (data.products) {
    aggregatedData.prestashop.products = data.products;
  }

  if (data.date && data.sessions !== undefined) {
    aggregatedData.bigquery.analyticsData.push(data);
  }

  if (data.product_id && data.total_sales !== undefined) {
    aggregatedData.bigquery.productPerformance.push(data);
  }

  if (data.activeUsers !== undefined) {
    aggregatedData.googleAnalytics.trafficData.push(data);
    aggregatedData.googleAnalytics.summary.totalUsers += parseInt(data.activeUsers || 0);
    aggregatedData.googleAnalytics.summary.totalSessions += parseInt(data.sessions || 0);
    aggregatedData.googleAnalytics.summary.totalConversions += parseInt(data.conversions || 0);
    aggregatedData.googleAnalytics.summary.totalRevenue += parseFloat(data.totalRevenue || 0);
  }
});

return [{ json: aggregatedData }];

// Estrai la struttura dati per Looker Studio dalla risposta dell'AI
const aiResponse = $input.first().json;
const analysisText = aiResponse.output || aiResponse.text || JSON.stringify(aiResponse);

// Prepara i dati per BigQuery/Looker Studio
const now = new Date();
const timestamp = now.toISOString();

// Struttura base per le tabelle Looker Studio
const lookerData = {
  analysis_report: {
    report_id: `report_${now.getTime()}`,
    generated_at: timestamp,
    analysis_content: analysisText,
    period_start: new Date(now.setDate(now.getDate() - 30)).toISOString().split('T')[0],
    period_end: new Date().toISOString().split('T')[0]
  },

  // Metriche giornaliere aggregate
  daily_metrics: {
    date: new Date().toISOString().split('T')[0],
    total_orders: 0,
    total_revenue: 0,
    total_sessions: 0,
    total_users: 0,
    conversion_rate: 0,
    avg_order_value: 0
  },

  // Dati per la dashboard
  dashboard_config: {
    recommended_charts: [
      'revenue_trend_line',
      'orders_by_channel_pie',
      'product_performance_bar',
      'traffic_sources_sankey',
      'conversion_funnel',
      'device_breakdown_donut',
      'geographic_heatmap',
      'kpi_scorecards'
    ],
    refresh_schedule: '6_hours',
    alert_thresholds: {
      revenue_drop_percent: 20,
      conversion_drop_percent: 15,
      traffic_drop_percent: 25
    }
  }
};

return [
  { json: { type: 'analysis_report', data: lookerData.analysis_report } },
  { json: { type: 'daily_metrics', data: lookerData.daily_metrics } },
  { json: { type: 'dashboard_config', data: lookerData.dashboard_config } },
  { json: { type: 'full_analysis', content: analysisText } }
];
